import Darwin
import Domain
import Foundation
@testable import MLInfrastructure
import Testing

// suiteRoot = the-record-suite/ (monorepo root, 3 hops up from this file)
private let suiteRoot = URL(fileURLWithPath: #filePath)
    .deletingLastPathComponent() // Unit/
    .deletingLastPathComponent() // Tests/
    .deletingLastPathComponent() // Record-ML/
    .deletingLastPathComponent() // repo root

private func countOpenFDs() -> Int {
    var count = 0
    for fd: Int32 in 0 ..< getdtablesize() where fcntl(fd, F_GETFD) != -1 {
        count += 1
    }
    return count
}

/// Source-inspection tests for MCP subprocess lifecycle (#29),
/// DuckDB command-server teardown (#44), and Pipe FD leak (#228).
///
/// Behavioral testing of process termination would require spawning real
/// subprocesses; source inspection verifies the wiring is present and
/// catches regressions when these files are refactored.
@Suite("MCPLifecycle")
struct MCPLifecycleTests {
    // MARK: - #29 MCPSummarizationPlugin.shutdown()

    @Test("MCPSummarizationPlugin declares shutdown() method")
    func mcpSummarizationPluginHasShutdown() throws {
        let source = try String(
            contentsOf: URL(fileURLWithPath: #filePath)
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .appendingPathComponent(
                    "Record-ML/Sources/MLInfrastructure/Summarization/MCPSummarizationPlugin.swift"
                ),
            encoding: .utf8
        )
        #expect(source.contains("func shutdown()"))
    }

    @Test("MCPSummarizationPlugin.shutdown() terminates process and resets ready state")
    func mcpSummarizationPluginShutdownResetsState() async {
        let plugin = MCPSummarizationPlugin(launchPath: "/nonexistent/binary")
        // No model loaded — shutdown on a clean plugin must not crash and
        // must leave isReady() == false.
        await plugin.shutdown()
        #expect(await plugin.isReady() == false)
    }

    // MARK: - #44 AppAssembler.teardown() + TheRecordApp.applicationWillTerminate

    @Test("AppAssembler source declares teardown() method")
    func appAssemblerHasTeardown() throws {
        let source = try String(
            contentsOf: suiteRoot.appendingPathComponent("Record-App/Sources/TheRecord/AppAssembler.swift"),
            encoding: .utf8
        )
        #expect(source.contains("func teardown()"))
        #expect(source.contains("withAsyncTeardown"))
        #expect(source.contains("storage?.close()"))
    }

    // MARK: - #228 Pipe FD leak — shutdown and deinit must close FileHandles

    @Test("MCPSummarizationPlugin.shutdown() closes pipe FileHandles (#228)")
    func shutdownClosesPipeFileHandles() throws {
        let source = try String(
            contentsOf: URL(fileURLWithPath: #filePath)
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .appendingPathComponent(
                    "Record-ML/Sources/MLInfrastructure/Summarization/MCPSummarizationPlugin.swift"
                ),
            encoding: .utf8
        )
        let shutdownStart = try #require(source.range(of: "func shutdown()"))
        let afterShutdown = source[shutdownStart.lowerBound...]
        let nextFuncOrDeinit = afterShutdown.dropFirst(1).range(of: "func ") ?? afterShutdown.endIndex ..< afterShutdown
            .endIndex
        let shutdownBody = String(afterShutdown[..<nextFuncOrDeinit.lowerBound])
        #expect(
            shutdownBody.contains("closeFile()"),
            "shutdown() must explicitly close pipe FileHandles to prevent FD leak (#228)"
        )
    }

    @Test("MCPSummarizationPlugin.deinit closes pipe FileHandles (#228)")
    func deinitClosesPipeFileHandles() throws {
        let source = try String(
            contentsOf: URL(fileURLWithPath: #filePath)
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .appendingPathComponent(
                    "Record-ML/Sources/MLInfrastructure/Summarization/MCPSummarizationPlugin.swift"
                ),
            encoding: .utf8
        )
        let deinitStart = try #require(source.range(of: "deinit {"))
        let afterDeinit = source[deinitStart.lowerBound...]
        let closingBrace = try #require(afterDeinit.dropFirst(1).range(of: "}"))
        let deinitBody = String(afterDeinit[...closingBrace.lowerBound])
        #expect(deinitBody.contains("closeFile()"), "deinit must close pipe FileHandles as defense-in-depth (#228)")
    }

    @Test("MCPSummarizationPlugin load+shutdown cycle does not leak FDs (#228)")
    func noFDLeakOnLoadShutdownCycle() async throws {
        let baseline = countOpenFDs()

        for _ in 0 ..< 5 {
            let plugin = MCPSummarizationPlugin(launchPath: "/bin/sleep", arguments: ["60"])
            try await plugin.loadModel(SummaryConfig.default)
            await plugin.shutdown()
        }

        try await Task.sleep(for: .milliseconds(300))
        let after = countOpenFDs()
        #expect(after - baseline <= 6, "FD leak: \(after - baseline) FDs leaked after 5 load/shutdown cycles (#228)")
    }

    @Test("TheRecordApp source wires applicationWillTerminate to assembler teardown")
    func appWiresTeardown() throws {
        let source = try String(
            contentsOf: suiteRoot.appendingPathComponent("Record-App/Sources/TheRecord/App.swift"),
            encoding: .utf8
        )
        #expect(source.contains("applicationWillTerminate"))
        #expect(source.contains("assembler.teardown()"))
    }
}

