/// Awaited from `applicationShouldTerminate` (#44, #280) so shutdown
/// completes before the process exits — previously the detector shutdown
/// was fire-and-forget and the database pool was never closed.
func teardown() async {
    transcriptionBuilt?.prewarmTask.cancel()
    searchSyncTask?.cancel()
    await withAsyncTeardown {
        if let detector = calendarAwareMeetingDetector {
            await detector.shutdown()
        }
    } teardown: {
        // Storage must close even if detector shutdown misbehaves.
        do {
            try await storage?.close()
        } catch {
            logger.error("Storage close during teardown failed: \(error.localizedDescription, privacy: .public)")
        }
    }
}

// sequential setup — extraction would harm readability
// swiftlint:disable:next function_body_length
func assemble(config: AppConfig, enableCoreAudioListeners: Bool = true) async -> Assembled {
    taskBag = TaskBag()
    let st = await buildStorage()
    // #216: composition root wiring — was constructed inline in TheRecordApp.
    let speakerProfileStore = JSONSpeakerProfileStore()
    // Resolve the commitment use case once — both engine and VM share the same instance.
    let sharedTrackUseCase = trackCommitmentsUseCase ?? TrackCommitmentsUseCase(store: InMemoryCommitmentStore())

    let alignUseCase = AlignTranscriptUseCase(
        sampleLoader: AudioFileLoader(),
        reader: st,
        writer: st
    )
    // #213: real PrivacyModeProvider, seeded from the persisted setting, so
    // ExportTranscriptUseCase/QueryContextUseCase/GenericMCPProvider stop
    // seeing nil and their privacy-mode guards actually execute.
    let privacyModeProvider = LivePrivacyModeProvider(initialMode: config.privacyMode)
    let (_, engine, suggestionsVM, queryContext) = buildEngine(
        config: config,
        fallbackTrack: sharedTrackUseCase,
        alignment: alignUseCase,
        privacyModeProvider: privacyModeProvider
    )
    let (libVM, migrationTask) = buildLibraryVM(storage: st)
    let (menuBarVM, pipelineCoordinator) = buildMenuBarVM(
        storage: st, engine: engine, suggestionsVM: suggestionsVM,
        migrationTask: migrationTask, config: config, queryContext: queryContext,
        enableCoreAudioListeners: enableCoreAudioListeners

import Foundation
import Testing

/// Source-inspection tests verifying `AppAssembler`/`AppAssemblerBuilders`/`App.swift`
/// wire a real `LivePrivacyModeProvider` into every consumer that previously
/// always received `nil`.
///
/// These tests inspect source because `AppAssembler` lives in the `TheRecord`
/// executable target (not a testable library from this test target, same
/// constraint documented in `AppAssemblerMCPWiringTests`). They act as
/// compile-time ratchets — if the wiring is removed, the test fails.
///
/// Context: #213 — `PrivacyModeProvider` had zero production conformances.
/// `ExportTranscriptUseCase`, `QueryContextUseCase`, and `GenericMCPProvider`
/// all accepted an optional provider defaulting to `nil`, so the privacy-mode
/// guards inside them never fired.
@Suite("AppAssembler — PrivacyModeProvider wiring (C3, #213)")
struct AppAssemblerPrivacyModeWiringTests {
    private static func sourceFile(_ name: String) -> String {
        // #filePath → …/Record-App/Tests/Unit/Presentation/AppAssemblerPrivacyModeWiringTests.swift
        // Go up 4 levels to the Record-App package root, then into Sources/TheRecord/.
        let thisFile = URL(fileURLWithPath: #filePath)
        let sourceURL = thisFile
            .deletingLastPathComponent() // Presentation/ → Unit/
            .deletingLastPathComponent() // Unit/ → Tests/
            .deletingLastPathComponent() // Tests/ → Record-App (package root)
            .deletingLastPathComponent() // Record-App → worktree root
            .appendingPathComponent("Sources/TheRecord/\(name)")
        return (try? String(contentsOf: sourceURL, encoding: .utf8)) ?? ""
    }

    private static let assemblerSource = sourceFile("AppAssembler.swift")
    private static let buildersSource = sourceFile("AppAssemblerBuilders.swift")
    private static let appSource = sourceFile("App.swift")

    // AC1: assemble(config:) constructs a LivePrivacyModeProvider seeded from
    // the persisted AppConfig, instead of never constructing one at all.
    @Test("assemble(config:) constructs a LivePrivacyModeProvider seeded from config.privacyMode")
    func assemblerConstructsLivePrivacyModeProvider() {
        #expect(
            Self.assemblerSource.contains("LivePrivacyModeProvider(initialMode: config.privacyMode)"),
            "assemble(config:) must construct a LivePrivacyModeProvider seeded from config.privacyMode"
        )
    }

    // AC2: Assembled exposes the provider so App.swift can keep it in sync
    // with live setting changes and thread it into ExportTranscriptUseCase.
    @Test("Assembled exposes privacyModeProvider")
    func assembledExposesPrivacyModeProvider() {
        #expect(
            Self.assemblerSource.contains("let privacyModeProvider: LivePrivacyModeProvider"),
            "AppAssembler.Assembled must expose privacyModeProvider so the composition root can reuse it"
        )
    }

    // AC3: buildEngine threads privacyModeProvider into QueryContextUseCase
    // instead of leaving it nil.
    @Test("buildEngine threads privacyModeProvider into QueryContextUseCase")
    func buildEngineWiresQueryContextUseCase() {
        #expect(
            Self.buildersSource.contains("QueryContextUseCase(") &&
                Self.buildersSource.contains("privacyModeProvider: privacyModeProvider"),
            "buildEngine must pass privacyModeProvider into QueryContextUseCase instead of leaving it nil"
        )
    }

    // AC4: buildMCPProviders threads privacyModeProvider into GenericMCPProvider
    // instead of leaving it nil.
    @Test("buildMCPProviders threads privacyModeProvider into GenericMCPProvider")
    func buildMCPProvidersWiresGenericMCPProvider() {
        #expect(
            Self.buildersSource.contains("GenericMCPProvider(") &&
                Self.buildersSource.contains("privacyModeProvider: privacyModeProvider"),
            "buildMCPProviders must pass privacyModeProvider into GenericMCPProvider instead of leaving it nil"
        )
    }

    // AC5: App.swift wires the same assembled provider into ExportTranscriptUseCase
    // via BroadsheetAppState, instead of relying on the nil-default init.
    @Test("App.swift wires ExportTranscriptUseCase to the live privacyModeProvider")
    func appWiresExportTranscriptUseCase() {
        #expect(
            Self.appSource.contains("ExportTranscriptUseCase(privacyModeProvider:"),
            "App.swift must construct BroadsheetAppState with an ExportTranscriptUseCase wired to the real privacyModeProvider"
        )
    }

    // AC6: setupPrivacyModeObserver forwards user-driven changes to the live
    // provider so it stays in sync after launch, not just at construction time.
    @Test("setupPrivacyModeObserver forwards privacyModeChanged notifications to the live provider")
    func appForwardsPrivacyModeChangesToProvider() {
        #expect(
            Self.appSource.contains("privacyModeProvider?.updateMode(mode)"),
            "setupPrivacyModeObserver must forward the changed mode to the live provider's updateMode"
        )
    }
}

