import CoreML
import Domain
import Foundation
import Logging
import Utilities
import WhisperKit

// MARK: - WhisperKitPlugin

// Error mapping: initializationError→aneCompilationFailed, modelsUnavailable/tokenizerUnavailable
// →modelNotLoaded, all inference errors→inferenceFailed, TimeoutError→timeout(300).

/// ANE-optimised WhisperKit transcription engine.
///
/// ## ANE Strategy (Granola pattern)
/// Encoder runs on Apple Neural Engine for heavy matrix operations (~3x speedup).
/// Decoder runs on CPU for lightweight token generation (lower power draw).
///
/// ## Thread Safety
/// All mutable state (`whisperKit`, `loadedModelId`, `sequenceCounter`) is
/// actor-isolated. No unchecked-Sendable workaround is required.
///
/// `WhisperKit` is a non-Sendable class and never crosses isolation boundaries.
/// The `withTimeout` closure captures `self` (this actor, which IS `Sendable`)
/// and calls the actor-isolated `runTranscription(samples:)` helper. That method
/// accesses `whisperKit` entirely on the actor's executor so the non-Sendable
/// reference stays within a single isolation domain at all times.
public actor WhisperKitPlugin: TranscriptionEngine {
    // MARK: - Intermediate DTO

    ///
    /// `WhisperKit.TranscriptionSegment` cannot be named via `WhisperKit.<Type>`
    /// because the compiler resolves the `WhisperKit.` qualifier to the class, not
    /// the module. This private struct captures only the fields that `buildSegment`
    /// needs (text, start, end, avgLogprob), all of which are primitive types that
    /// cross the actor isolation boundary safely.
    struct ExtractedSegment {
        let text: String
        let start: Float
        let end: Float
        let avgLogprob: Float
    }

    // MARK: - Actor State

    private var whisperKit: WhisperKit?
    private var loadedModelId: ModelID?
    private var sequenceCounter = 0
    private var lastComputeUnit: ComputeUnit = .unknown
    public private(set) var downloadDelegate: (any ModelDownloadDelegate)?

    private let logger = AppLogger.for(category: "WhisperKit")

    // MARK: - Init

    public init() {}

    public func setDownloadDelegate(_ delegate: (any ModelDownloadDelegate)?) {
        downloadDelegate = delegate
    }

    // MARK: - TranscriptionEngine

    public func loadModel(_ modelId: ModelID) async throws {
        // Idempotent: skip if the same model is already loaded and ready.
        if loadedModelId == modelId, whisperKit != nil {
            logger.info("Model '\(modelId, privacy: .public)' already loaded — skipping")
            return
        }

        logger.info("Loading WhisperKit model '\(modelId, privacy: .public)'")
        await downloadDelegate?.downloadProgress(.init(modelId: modelId, fractionCompleted: 0.0, phase: .downloading))

        // ANE-first: encoder on ANE (heavy matrix ops), decoder on CPU (lightweight).
        let computeOptions = ModelComputeOptions(
            melCompute: .cpuAndGPU,
            audioEncoderCompute: .cpuAndNeuralEngine,
            textDecoderCompute: .cpuOnly
        )
        lastComputeUnit = .cpuAndNeuralEngine

        do {
            // Respect cancellation before starting the download (e.g. if a caller wraps
            // loadModel in withTimeout and the deadline fires before we begin).
            try Task.checkCancellation()
            let kit = try await WhisperKit(
                model: modelId.rawValue,
                computeOptions: computeOptions,
                verbose: false,
                logLevel: .none,
                prewarm: false,
                load: true,
                download: true
            )
            whisperKit = kit
            loadedModelId = modelId
            await downloadDelegate?.downloadProgress(.init(modelId: modelId, fractionCompleted: 0.8, phase: .compiling))
            logger.info("WhisperKit model '\(modelId, privacy: .public)' loaded")
            // warmUp() translates its own errors into TranscriptionError.
            // Catch TranscriptionError first to avoid double-wrapping in the
            // WhisperError handler below.
            try await warmUp()
            await downloadDelegate?.downloadProgress(.init(modelId: modelId, fractionCompleted: 1.0, phase: .ready))
        } catch let error as TranscriptionError {
            whisperKit = nil
            loadedModelId = nil
            throw error
        } catch let error as WhisperError {
            let errDesc = String(reflecting: error)
            logger.error("Load error: \(errDesc, privacy: .private)")
            whisperKit = nil
            loadedModelId = nil
            throw mapLoadError(error)
        } catch let error as ArgmaxCoreError {
            let errDesc = String(reflecting: error)
            logger.error("Load error: \(errDesc, privacy: .private)")
            whisperKit = nil
            loadedModelId = nil
            throw TranscriptionError.modelNotLoaded(underlying: error)
        } catch {
            let errDesc = String(reflecting: error)
            logger.error("Load error: \(errDesc, privacy: .private)")
            whisperKit = nil
            loadedModelId = nil
            throw TranscriptionError.modelNotLoaded(underlying: error)
        }
    }

    public func transcribe(
        samples: [Float],
        context: TranscriptionContext
    ) async throws -> Domain.TranscriptionSegment {
        guard !samples.isEmpty else { throw TranscriptionError.audioTooShort }
        guard whisperKit != nil else { throw TranscriptionError.modelNotLoaded(underlying: nil) }
        logger.debug(
            // swiftlint:disable:next line_length
            "Transcribing \(samples.count, privacy: .public) samples | session: \(context.sessionId?.rawValue ?? "none", privacy: .private)"
        )
        let rawData = try await fetchRawData(samples: samples)
        let seqNum = sequenceCounter
        sequenceCounter += 1
        return buildSegment(
            segments: rawData.segments,
            fallbackText: rawData.fallbackText,
            context: context,
            sequenceNumber: seqNum
        )
    }

    /// Returns one ``TranscriptionSegment`` per WhisperKit chunk so that
    /// downstream diarization can align speaker boundaries with fine-grained
    /// timestamps instead of a single blob spanning the whole recording.
    public func transcribeSegments(
        samples: [Float],
        context: TranscriptionContext
    ) async throws -> [Domain.TranscriptionSegment] {
        guard !samples.isEmpty else { throw TranscriptionError.audioTooShort }
        guard whisperKit != nil else { throw TranscriptionError.modelNotLoaded(underlying: nil) }
        let rawData = try await fetchRawData(samples: samples)
        guard !rawData.segments.isEmpty else {
            let seqNum = sequenceCounter
            sequenceCounter += 1
            return [buildSegment(
                segments: [],
                fallbackText: rawData.fallbackText,
                context: context,
                sequenceNumber: seqNum
            )]
        }
        // Safe: .map executes synchronously after the await returns — no reentrancy gap on sequenceCounter.
        return rawData.segments.map { extracted in
            let seqNum = sequenceCounter
            sequenceCounter += 1
            return buildSingleSegment(extracted, context: context, sequenceNumber: seqNum)
        }
    }

    public func unloadModel() async {
        whisperKit = nil
        loadedModelId = nil
        logger.info("WhisperKit model unloaded")
    }

    public func isReady() async -> Bool {
        whisperKit != nil
    }

    public func getComputeUnit() async -> ComputeUnit {
        lastComputeUnit
    }

    public func warmUp() async throws(TranscriptionError) {
        guard let kit = whisperKit else {
            throw TranscriptionError.modelNotLoaded(underlying: nil)
        }
        logger.info("Running ANE warm-up pass (CoreML model compilation)")
        do {
            try await kit.prewarmModels()
            logger.info("ANE warm-up complete")
        } catch let error as WhisperError {
            if case .initializationError = error {
                throw TranscriptionError.aneCompilationFailed
            }
            throw TranscriptionError.modelNotLoaded(underlying: error)
        } catch {
            throw TranscriptionError.modelNotLoaded(underlying: error)
        }
    }

    // MARK: - Private Inference Helpers

    /// Shared timeout + error-mapping wrapper used by both `transcribe` and
    /// `transcribeSegments`. Keeps the 300 s budget and WhisperError translation in
    /// one place so they can't drift apart.
    func fetchRawData(
        samples: [Float]
    ) async throws -> (segments: [ExtractedSegment], fallbackText: String) {
        do {
            return try await withTimeout(TimeoutConfig.whisperKitInference) {
                try await self.runTranscription(samples: samples)
            }
        } catch is TimeoutError {
            let tc = TimeoutConfig.whisperKitInference.components
            throw TranscriptionError.timeout(duration: TimeInterval(tc.seconds) + TimeInterval(tc.attoseconds) * 1e-18)
        } catch is CancellationError {
            throw CancellationError()
        } catch let error as WhisperError {
            throw mapInferenceError(error)
        } catch let error as TranscriptionError {
            throw error
        } catch {
            throw TranscriptionError.inferenceFailed(underlying: error)
        }
    }

    /// Calls WhisperKit's `transcribe` within actor isolation.
    ///
    /// `WhisperKit` is a non-Sendable class. Confining all access to this
    /// actor-isolated method keeps the reference within a single isolation domain.
    func runTranscription(
        samples: [Float]
    ) async throws -> (segments: [ExtractedSegment], fallbackText: String) {
        guard let kit = whisperKit else {
            throw TranscriptionError.modelNotLoaded(underlying: nil)
        }

        try Task.checkCancellation()

        let results = try await kit.transcribe(
            audioArray: samples,
            decodeOptions: nil,
            callback: { _ in
                if Task.isCancelled {
                    return false
                }
                return true
            }
        )

        try Task.checkCancellation()

        let segments = results.flatMap { result in
            result.segments.map { seg in
                ExtractedSegment(
                    text: Self.stripTimestampTokens(seg.text),
                    start: seg.start,
                    end: seg.end,
                    avgLogprob: seg.avgLogprob
                )
            }
        }
        let fallbackText = results.map { Self.stripTimestampTokens($0.text) }.joined(separator: " ")
        return (segments, fallbackText)
    }
}

import Domain
import FluidAudio
import Foundation

// MARK: - OfflineDiarizationTuning

/// Tuning for the offline (batch) VBx diarization pipeline.
///
/// Defaults are the measured destination-pipeline values from the #308
/// ProofHarness sweeps (2026-07): pure AHC→VBx with no speaker-count bounds
/// is deterministic (bounds trigger FluidAudio's KMeans fallback, which is
/// initialization-sensitive), the AHC threshold sits mid-plateau, and a
/// centroid-merge second pass repairs over-clustering without a count prior.
///
/// Measured against RTTM ground truth (no collar):
/// meeting-15min 85.1% purity / 28.2% DER (oracle ceiling 87.5% / 26.2%),
/// AMI ES2004a 83.3% / 24.2% (oracle 83.7% / 23.8%). Shipped streaming
/// engine on the same fixture: 78.0% / 35.8%.
public struct OfflineDiarizationTuning: Sendable, Equatable {
    /// AHC threshold. On these fixtures higher → more clusters; 0.8–0.9 is a
    /// stable plateau on both synthetic and AMI fixtures.
    public var clusteringThreshold: Double

    /// Segmentation window hop as a fraction of window length. 0.1 matches
    /// pyannote reference accuracy; FluidAudio's 0.2 default trades ~1.4%
    /// DER for speed.
    public var segmentationStepRatio: Double

    /// Minimum silence (seconds) before a segment is split — NeMo DIHARD3
    /// post-processing recipe value.
    public var minSilenceToSplit: Double

    /// Cosine-similarity floor for the pass-2 centroid merge. 0.6 merges
    /// duplicate clusters of one speaker; 0.5 is too aggressive (merges
    /// distinct same-gender speakers).
    public var centroidMergeThreshold: Double

    public init(
        clusteringThreshold: Double = 0.85,
        segmentationStepRatio: Double = 0.1,
        minSilenceToSplit: Double = 0.15,
        centroidMergeThreshold: Double = 0.6
    ) {
        self.clusteringThreshold = clusteringThreshold
        self.segmentationStepRatio = segmentationStepRatio
        self.minSilenceToSplit = minSilenceToSplit
        self.centroidMergeThreshold = centroidMergeThreshold
    }

    /// The validated destination-pipeline configuration.
    public static let recommended = OfflineDiarizationTuning()
}

// MARK: - OfflineDiarizationPlugin

/// Batch speaker diarization backed by FluidAudio's `OfflineDiarizerManager`
/// (pyannote community-1 powerset segmentation + AHC→VBx clustering), with a
/// second centroid-merge pass over the exposed chunk embeddings.
///
/// Unlike `FluidDiarizationPlugin` (streaming, incremental speaker
/// enrollment), this engine sees the whole recording at once, which is what
/// `DiarizationEngine.diarize(samples:sampleRate:)` already provides. The
/// pipeline is deterministic: byte-identical output across runs for the same
/// input.
public actor OfflineDiarizationPlugin: DiarizationEngine {
    /// `OfflineDiarizerManager` is not `Sendable`, so it cannot be held as
    /// actor state across its `async` calls. Instead each call builds a
    /// region-local manager; after `prepare()` has warmed FluidAudio's
    /// on-disk model cache, per-call model loading is cheap relative to the
    /// batch inference itself.
    private var prepared = false
    private let tuning: OfflineDiarizationTuning

    public init(tuning: OfflineDiarizationTuning = .recommended) {
        self.tuning = tuning
    }

    private func makeConfig() -> OfflineDiarizerConfig {
        var config = OfflineDiarizerConfig()
        config.clustering.threshold = tuning.clusteringThreshold
        config.segmentation.stepRatio = tuning.segmentationStepRatio
        config.segmentation.minDurationOff = tuning.minSilenceToSplit
        config.exposeChunkEmbeddings = true
        return config
    }

    // MARK: DiarizationEngine

    public func prepare() async throws {
        guard !prepared else { return }
        do {
            try await OfflineDiarizerManager(config: makeConfig()).prepareModels()
        } catch {
            throw TranscriptionError.modelNotLoaded(underlying: error)
        }
        prepared = true
    }

    public func diarize(samples: [Float], sampleRate: Int) async throws -> [SpeakerSegment] {
        guard prepared else {
            throw TranscriptionError.modelNotLoaded(underlying: nil)
        }
        let segments: [SpeakerSegment]
        let chunks: [ChunkEmbedding]
        do {
            let manager = OfflineDiarizerManager(config: makeConfig())
            try await manager.prepareModels()
            let raw = try await manager.process(audio: samples)
            segments = raw.segments.map { seg in
                SpeakerSegment(
                    speakerId: SpeakerID(seg.speakerId),
                    startTime: TimeInterval(seg.startTimeSeconds),
                    endTime: TimeInterval(seg.endTimeSeconds),
                    confidence: Double(seg.qualityScore)
                )
            }
            chunks = raw.chunkEmbeddings ?? []
        } catch {
            throw TranscriptionError.inferenceFailed(underlying: error)
        }
        let merges = Self.centroidMerges(
            chunks: chunks, threshold: tuning.centroidMergeThreshold
        )
        return Self.applyMerges(merges, to: segments)
    }

    public func isReady() async -> Bool {
        prepared
    }

