import Domain
import FluidAudio
import Foundation
import Logging

// MARK: - OfflineDiarizationTuning

/// Tuning for the offline (batch) VBx diarization pipeline.
///
/// Defaults are the measured destination-pipeline values from the #308
/// ProofHarness sweeps (2026-07): pure AHC→VBx with no speaker-count bounds
/// is deterministic (bounds trigger FluidAudio's KMeans fallback, which is
/// initialization-sensitive), the AHC threshold sits mid-plateau, and a
/// centroid-merge second pass repairs over-clustering without a count prior.
///
/// Measured against RTTM ground truth (no collar):
/// meeting-15min 85.1% purity / 28.2% DER (oracle ceiling 87.5% / 26.2%),
/// AMI ES2004a 83.3% / 24.2% (oracle 83.7% / 23.8%). Shipped streaming
/// engine on the same fixture: 78.0% / 35.8%.
public struct OfflineDiarizationTuning: Sendable, Equatable {
    /// AHC threshold. On these fixtures higher → more clusters; 0.8–0.9 is a
    /// stable plateau on both synthetic and AMI fixtures.
    public var clusteringThreshold: Double

    /// Segmentation window hop as a fraction of window length. 0.1 matches
    /// pyannote reference accuracy; FluidAudio's 0.2 default trades ~1.4%
    /// DER for speed.
    public var segmentationStepRatio: Double

    /// Minimum silence (seconds) before a segment is split — NeMo DIHARD3
    /// post-processing recipe value.
    public var minSilenceToSplit: Double

    /// Cosine-similarity floor for the pass-2 centroid merge. 0.6 merges
    /// duplicate clusters of one speaker; 0.5 is too aggressive (merges
    /// distinct same-gender speakers).
    public var centroidMergeThreshold: Double

    public init(
        clusteringThreshold: Double = 0.85,
        segmentationStepRatio: Double = 0.1,
        minSilenceToSplit: Double = 0.15,
        centroidMergeThreshold: Double = 0.6
    ) {
        self.clusteringThreshold = clusteringThreshold
        self.segmentationStepRatio = segmentationStepRatio
        self.minSilenceToSplit = minSilenceToSplit
        self.centroidMergeThreshold = centroidMergeThreshold
    }

    /// The validated destination-pipeline configuration.
    public static let recommended = OfflineDiarizationTuning()
}

// MARK: - OfflineDiarizationPlugin

/// Batch speaker diarization backed by FluidAudio's `OfflineDiarizerManager`
/// (pyannote community-1 powerset segmentation + AHC→VBx clustering), with a
/// second centroid-merge pass over the exposed chunk embeddings.
///
/// Unlike `FluidDiarizationPlugin` (streaming, incremental speaker
/// enrollment), this engine sees the whole recording at once, which is what
/// `DiarizationEngine.diarize(samples:sampleRate:)` already provides. The
/// pipeline is deterministic: byte-identical output across runs for the same
/// input.
public actor OfflineDiarizationPlugin: DiarizationEngine {
    /// `OfflineDiarizerManager` is not `Sendable`, so it cannot be held as
    /// actor state across its `async` calls. Instead each call builds a
    /// region-local manager; after `prepare()` has warmed FluidAudio's
    /// on-disk model cache, per-call model loading is cheap relative to the
    /// batch inference itself.
    private var prepared = false
    private let tuning: OfflineDiarizationTuning
    /// #109: Instruments-visible stage intervals (model prepare, full batch
    /// job). Filter Instruments to app.the-record:Performance.
    private let signposter = AppLogger.signposter(category: "Performance")

    public init(tuning: OfflineDiarizationTuning = .recommended) {
        self.tuning = tuning
    }

    private func makeConfig() -> OfflineDiarizerConfig {
        var config = OfflineDiarizerConfig()
        config.clustering.threshold = tuning.clusteringThreshold
        config.segmentation.stepRatio = tuning.segmentationStepRatio
        config.segmentation.minDurationOff = tuning.minSilenceToSplit
        config.exposeChunkEmbeddings = true
        return config
    }

    // MARK: DiarizationEngine

    public func prepare() async throws {
        guard !prepared else { return }
        let loadState = signposter.beginInterval("loadModel", id: signposter.makeSignpostID())
        defer { signposter.endInterval("loadModel", loadState) }
        do {
            try await OfflineDiarizerManager(config: makeConfig()).prepareModels()
        } catch {
            throw TranscriptionError.modelNotLoaded(underlying: error)
        }
        prepared = true
    }

    public func diarize(samples: [Float], sampleRate: Int) async throws -> [SpeakerSegment] {
        guard prepared else {
            throw TranscriptionError.modelNotLoaded(underlying: nil)
        }
        let segments: [SpeakerSegment]
        let chunks: [ChunkEmbedding]
        do {
            let manager = OfflineDiarizerManager(config: makeConfig())
            try await manager.prepareModels()
            let raw = try await manager.process(audio: samples)
            segments = raw.segments.map { seg in
                SpeakerSegment(
                    speakerId: SpeakerID(seg.speakerId),
                    startTime: TimeInterval(seg.startTimeSeconds),
                    endTime: TimeInterval(seg.endTimeSeconds),
                    confidence: Double(seg.qualityScore)
                )
            }
            chunks = raw.chunkEmbeddings ?? []
        } catch {
            throw TranscriptionError.inferenceFailed(underlying: error)
        }
        let merges = Self.centroidMerges(
            chunks: chunks, threshold: tuning.centroidMergeThreshold
        )
        return Self.applyMerges(merges, to: segments)
    }

    public func isReady() async -> Bool {
        prepared
    }

    // MARK: Pass 2 — centroid cluster merging

    /// Compute duration-weighted L2-normalized centroids per cluster from the
    /// exposed chunk embeddings, then greedily merge the most-similar cluster
    /// pair while its cosine similarity exceeds `threshold`. Smaller total
    /// duration merges into larger. Returns old→surviving label mapping
    /// (transitively resolved).
    static func centroidMerges(
        chunks: [ChunkEmbedding], threshold: Double
    ) -> [String: String] {
        var sums: [String: [Double]] = [:]
        var durations: [String: Double] = [:]
        for chunk in chunks {
            let duration = max(0, chunk.endTimeSeconds - chunk.startTimeSeconds)
            guard duration > 0, !chunk.embedding256.isEmpty else { continue }
            let norm = sqrt(chunk.embedding256.reduce(0.0) { $0 + Double($1) * Double($1) })
            guard norm > 0 else { continue }
            var sum = sums[chunk.speakerId] ?? [Double](repeating: 0, count: chunk.embedding256.count)
            for i in 0..<chunk.embedding256.count {
                sum[i] += Double(chunk.embedding256[i]) / norm * duration
            }
            sums[chunk.speakerId] = sum
            durations[chunk.speakerId, default: 0] += duration
        }

        var merges: [String: String] = [:]
        var active = Set(sums.keys)
        while active.count > 1 {
            guard
                let pair = closestPair(
                    active: active, sums: sums, durations: durations, threshold: threshold
                ),
                let fromSum = sums[pair.from], var toSum = sums[pair.to]
            else { break }
            for i in 0..<min(fromSum.count, toSum.count) { toSum[i] += fromSum[i] }
            sums[pair.to] = toSum
            durations[pair.to, default: 0] += durations[pair.from, default: 0]
            sums[pair.from] = nil
            active.remove(pair.from)
            // Redirect earlier merges that pointed at the disappearing label.
            for (key, value) in merges where value == pair.from { merges[key] = pair.to }
            merges[pair.from] = pair.to
        }
        return merges
    }

    /// Relabel segments whose cluster was merged away by pass 2.
    static func applyMerges(
        _ merges: [String: String], to segments: [SpeakerSegment]
    ) -> [SpeakerSegment] {
        guard !merges.isEmpty else { return segments }
        return segments.map { seg in
            guard let target = merges[seg.speakerId.rawValue] else { return seg }
            return SpeakerSegment(
                speakerId: SpeakerID(target),
                startTime: seg.startTime,
                endTime: seg.endTime,
                confidence: seg.confidence
            )
        }
    }

    /// Most-similar active cluster pair at or above `threshold`, oriented so
    /// the smaller total duration merges into the larger. `nil` when no pair
    /// clears the threshold.
    private static func closestPair(
        active: Set<String>,
        sums: [String: [Double]],
        durations: [String: Double],
        threshold: Double
    ) -> (from: String, to: String)? {
        var bestPair: (from: String, to: String)?
        var bestSim = threshold
        let ordered = active.sorted()
        for (i, a) in ordered.enumerated() {
            guard let sumA = sums[a] else { continue }
            for b in ordered.dropFirst(i + 1) {
                guard let sumB = sums[b] else { continue }
                let sim = cosine(sumA, sumB)
                if sim >= bestSim {
                    bestSim = sim
                    bestPair =
                        durations[a, default: 0] < durations[b, default: 0]
                        ? (from: a, to: b) : (from: b, to: a)
                }
            }
        }
        return bestPair
    }

    private static func cosine(_ a: [Double], _ b: [Double]) -> Double {
        var dot = 0.0
        var normA = 0.0
        var normB = 0.0
        for i in 0..<min(a.count, b.count) {
            dot += a[i] * b[i]
            normA += a[i] * a[i]
            normB += b[i] * b[i]
        }
        let denominator = sqrt(normA) * sqrt(normB)
        return denominator > 0 ? dot / denominator : 0
    }
}

