import Domain
import Foundation
import Observation

@Observable
@MainActor
public final class ModelDownloadViewModel {
    // MARK: - State

    /// Full model list driving the download UI. Mutations trigger `modelsByCategory` recomputation.
    public var models: [ModelEntry] = ModelCatalog.all {
        didSet { modelsByCategory = Dictionary(grouping: models, by: \.category) }
    }

    /// Non-nil when a download fails; displayed as an inline error banner.
    public var errorMessage: String?
    /// Controls visibility of the custom model storage path picker sheet.
    public var isShowingPathPicker = false

    @ObservationIgnored
    private var downloadTasks: [String: Task<Void, Never>] = [:]

    @ObservationIgnored
    private let downloadWhisper: @Sendable (String, String?) async throws -> Void
    @ObservationIgnored
    private let downloadParakeet: @Sendable (String, String?) async throws -> Void
    @ObservationIgnored
    private let downloadMLX: @Sendable (String, String?) async throws -> Void
    @ObservationIgnored
    private let downloadDiarization: @Sendable () async throws -> Void

    // MARK: - Persisted settings

    @ObservationIgnored
    private let tokenStore: any TokenStore

    /// Cached once in init — avoids a Keychain read on every SwiftUI body eval.
    /// Persisted via the injected `TokenStore` on every change.
    public var hfToken: String {
        didSet {
            let newToken = hfToken
            let store = tokenStore
            // try? is intentional: didSet cannot be async or throw, and a Keychain
            // write failure in a fire-and-forget Task has no meaningful caller to
            // propagate to. The token is already cached in memory for this session.
            Task {
                if newToken.isEmpty {
                    try? store.deleteToken() // swiftlint:disable:this superfluous_disable_command
                } else {
                    try? store.saveToken(newToken) // swiftlint:disable:this superfluous_disable_command
                }
            }
        }
    }

    public var modelStoragePath: String {
        get {
            UserDefaults.standard.string(forKey: "therecord.modelStoragePath")
                ?? (
                    FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)
                        .first?.appendingPathComponent(AppConstants.Paths.huggingFaceHubPath).path ?? ""
                )
        }
        set { UserDefaults.standard.set(newValue, forKey: "therecord.modelStoragePath") }
    }

    // MARK: - Init

    public init(
        downloadWhisper: @escaping @Sendable (String, String?) async throws -> Void,
        downloadParakeet: @escaping @Sendable (String, String?) async throws -> Void,
        downloadMLX: @escaping @Sendable (String, String?) async throws -> Void,
        downloadDiarization: @escaping @Sendable () async throws -> Void,
        tokenStore: any TokenStore
    ) {
        self.downloadWhisper = downloadWhisper
        self.downloadParakeet = downloadParakeet
        self.downloadMLX = downloadMLX
        self.downloadDiarization = downloadDiarization
        self.tokenStore = tokenStore
        hfToken = (try? tokenStore.loadToken()) ?? ""
    }

    // MARK: - Precomputed Groups

    /// Models grouped by category. Stored and updated via `models.didSet` — avoids
    /// rebuilding `Dictionary(grouping:)` on every access (#173).
    public private(set) var modelsByCategory: [ModelCategory: [ModelEntry]] =
        Dictionary(grouping: ModelCatalog.all, by: \.category)

    // MARK: - Actions

    public func checkAllStatuses() {
        let currentModels = models
        let currentStoragePath = modelStoragePath

        Task { [weak self] in
            let statuses = await Task.detached {
                var result: [ModelID: Bool] = [:]
                for model in currentModels {
                    result[model.id] = Self.checkIsDownloaded(model, storagePath: currentStoragePath)
                }
                return result
            }.value

            guard let self else { return }
            for i in self.models.indices {
                if let downloaded = statuses[self.models[i].id] {
                    self.models[i].status = downloaded ? .downloaded : .notDownloaded
                }
            }
        }
    }

    public func download(id: ModelID) {
        guard let idx = models.firstIndex(where: { $0.id == id }) else { return }
        guard !models[idx].status.isDownloading else { return }
        models[idx].status = .downloading(0)
        errorMessage = nil

        let token = hfToken.isEmpty ? nil : hfToken
        let model = models[idx]

        downloadTasks[id.rawValue]?.cancel()
        downloadTasks[id.rawValue] = Task { [weak self] in
            guard let self else { return }
            do {
                switch model.category {
                case .transcription:
                    if model.id == ModelIDs.parakeetPrimary {
                        try await downloadParakeet(model.id.rawValue, token)
                    } else {
                        try await downloadWhisper(model.id.rawValue, token)
                    }
                case .summarization:
                    try await downloadMLX(model.id.rawValue, token)
                case .diarization:
                    try await downloadDiarization()
                }
                if let i = self.models.firstIndex(where: { $0.id == id }) {
                    self.models[i].status = .downloaded
                    UserDefaults.standard.set(true, forKey: "therecord.modelDownloaded.\(id)")
                }
            } catch {
                if let i = self.models.firstIndex(where: { $0.id == id }) {
                    self.models[i].status = .failed(error.userFacingMessage)
                }
                self.errorMessage = "\(model.displayName): \(error.userFacingMessage)"
            }
            self.downloadTasks.removeValue(forKey: id.rawValue)
        }
    }

    // MARK: - Filesystem check

    private nonisolated static func checkIsDownloaded(_ model: ModelEntry, storagePath: String) -> Bool {
        // Trust a previously confirmed download — avoids fighting with WhisperKit's
        // internal cache layout (argmaxinc/whisperkit-coreml snapshot structure).
        if UserDefaults.standard.bool(forKey: "therecord.modelDownloaded.\(model.id)") { return true }

        let fm = FileManager.default
        switch model.category {
        case .diarization:
            let path = fm.urls(for: .applicationSupportDirectory, in: .userDomainMask)
                .first?.appendingPathComponent(AppConstants.Paths.fluidAudioDiarizationPath)
            return fm.fileExists(atPath: path?.path ?? "")

        case .summarization:
            // Check user-specified storage path first, then default HF cache
            let slug = model.hfRepo.replacingOccurrences(of: "/", with: "_")
            if fm.fileExists(atPath: storagePath + "/" + slug) { return true }
            let cache = fm.homeDirectoryForCurrentUser
                .appendingPathComponent(AppConstants.Paths.huggingFaceCacheBasePath)
                .appendingPathComponent("models--" + model.hfRepo.replacingOccurrences(of: "/", with: "--"))
            return fm.fileExists(atPath: cache.path)

        case .transcription:
            if model.id == ModelIDs.parakeetPrimary {
                let path = fm.urls(for: .applicationSupportDirectory, in: .userDomainMask)
                    .first?.appendingPathComponent(AppConstants.Paths.fluidAudioParakeetPath)
                return fm.fileExists(atPath: path?.path ?? "")
            }
            let base = fm.homeDirectoryForCurrentUser
                .appendingPathComponent(AppConstants.Paths.whisperKitSnapshotsPath)
            guard fm.fileExists(atPath: base.path) else { return false }
            do {
                let snapshots = try fm.contentsOfDirectory(atPath: base.path)
                return snapshots.contains {
                    fm
                        .fileExists(
                            atPath: base.appendingPathComponent($0).appendingPathComponent(model.id.rawValue)
                                .path
                        )
                }
            } catch {
                return false
            }
        }
    }
}

