import Business
import Domain
import Foundation
import Logging

// MARK: - Engine Fan-out

@MainActor
public extension MenuBarViewModel {
    // MARK: - Public Interface

    /// Schedules a background engine fan-out for the given transcription segments.
    ///
    /// Fires-and-forgets a Task so the recording-stop path is never blocked.
    ///
    /// # Post-stop fan-out, not live during-recording streaming
    ///
    /// Note: Live streaming fan-out is a future slice tracked by TASK-031.
    /// This method currently receives segments from the completed TranscriptionResult
    /// after `stopRecordingTapped()`.
    func feedToEngine(segments: [StreamingSegment], meetingId: RecordingID) {
        guard engine != nil else { return }
        engineFanOutTask?.cancel()
        engineFanOutTask = Task { [weak self] in
            await self?.runEngineFanOut(segments: segments, meetingId: meetingId)
        }
    }

    /// Convenience overload that maps ``TranscriptionSegment`` values to
    /// ``StreamingSegment`` before scheduling the engine fan-out.
    ///
    /// Callers that already hold `[StreamingSegment]` should use the primary
    /// overload directly to avoid the allocation cost of this mapping step.
    func feedToEngine(segments: [TranscriptionSegment], meetingId: RecordingID) {
        let streamingSegments = segments.map {
            StreamingSegment(text: $0.text, isFinal: $0.isFinal, track: .microphone, timestamp: $0.startTime)
        }
        feedToEngine(segments: streamingSegments, meetingId: meetingId)
    }

    // MARK: - Private

    private func runEngineFanOut(segments: [StreamingSegment], meetingId: RecordingID) async {
        guard let engine, let contextSuggestionsVM else { return }

        for segment in segments where !segment.text.isEmpty {
            guard !Task.isCancelled else { return }
            do {
                let suggestions = try await engine.handleSegment(segment, meetingId: meetingId)
                if !suggestions.isEmpty {
                    contextSuggestionsVM.updateSuggestions(suggestions)
                }
            } catch {
                // DPS Rule 1: engine errors are logged, not swallowed silently.
                // Rule 2: error boundary is acceptable at this fan-out point —
                // engine failure must never kill the transcription stream.
                let desc = String(describing: error)
                logger.error("TheRecordEngine.handleSegment failed — segment skipped: \(desc, privacy: .private)")
            }
        }
    }
}

        NotificationCenter.default.post(name: .recordingStopped, object: nil)
    }

    internal func handleRecordingCompleted(_ transcribed: TranscribedRecording) {
        lastTranscription = transcribed.transcription
        cleanupState = .idle
        pipelineState = .idle
        statusMessage = Self.readyStatus
        let recordingId = transcribed.recording.metadata.id
        cleanupRecordingId = recordingId

        Task { [weak self] in
            guard let self else { return }
            await pipelineCoordinator.startCleanupPass(for: recordingId)
            await pipelineCoordinator.startPipeline(for: recordingId, liveTranscription: transcribed.transcription)
        }

        feedToEngine(segments: transcribed.transcription.segments, meetingId: recordingId)
        engine?.recordingCompleted(recordingId: recordingId)
    }
}

import Foundation
import OSLog
import Domain

public actor SearchRecordingsUseCase {

    private let storage: any SearchRepository
    private let logger = Logger(subsystem: "app.the-record", category: "SearchRecordings")

    public init(storage: any SearchRepository) {
        self.storage = storage
    }

    /// NOTE: Pagination is supported via limit/offset parameters.
    public func search(query: String, limit: Int? = nil, offset: Int? = nil) async throws -> [RecordingSummary] {
        let trimmed = query.trimmingCharacters(in: .whitespaces)
        if trimmed.isEmpty {
            logger.info("Empty query — listing all recordings")
            return try await storage.listRecordings(limit: limit, offset: offset)
        }
        logger.info("Searching transcripts for: \(trimmed, privacy: .private)")
        return try await storage.searchTranscripts(query: trimmed, limit: limit, offset: offset)
    }
}

import Foundation

/// Named composition for search: recordings listing + transcript full-text
/// search (#151). Use cases inject `any SearchRepository` instead of an
/// inline compound existential, so growing search's storage needs means
/// changing this alias — not every signature that carries it.
public typealias SearchRepository = RecordingReadRepository & TranscriptReadRepository

import Testing
import Foundation
@testable import Business
import Domain
import TestMocks

@Suite("SearchRecordingsUseCase")
struct SearchRecordingsUseCaseTests {

    // MARK: - Helpers

    private func makeStoredRecording(
        id: RecordingID = RecordingID("rec-001"),
        transcript: String? = nil,
    ) -> StoredRecording {
        let meta = RecordingMetadata(
            id: id,
            recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
            duration: 60.0,
            fileSize: 1_048_576,
            audioURL: URL(fileURLWithPath: "/recordings/\(id.rawValue).wav"),
            transcriptURL: nil,
            modelId: ModelID("openai_whisper-tiny"),
            processingTime: 1.0,
            computeUnit: .cpuOnly,
            wordCount: transcript.map { $0.split(separator: " ").count } ?? 0,
        )
        var recording = StoredRecording(metadata: meta)
        if let text = transcript {
            let result = TranscriptionResult(
                segments: [],
                fullText: text,
                processingTime: 1.0,
                modelId: ModelID("openai_whisper-tiny"),
                recordedAt: meta.recordedAt,
                computeUnit: .cpuOnly,
                passType: .live,
            )
            recording = StoredRecording(metadata: meta, transcript: result)
        }
        return recording
    }

    // MARK: - Delegation

    @Test("execute with non-empty query delegates to storage.searchTranscripts")
    func executeWithNonEmptyQueryDelegatesToSearchTranscripts() async throws {
        let storage = MockStorageEngine()
        let useCase = SearchRecordingsUseCase(storage: storage)

        _ = try await useCase.search(query: "hello")

        let called = await storage.searchTranscriptsCalled
        #expect(called == true)
    }

    @Test("execute with empty string delegates to storage.listRecordings")
    func executeWithEmptyStringDelegatesToListRecordings() async throws {
        let storage = MockStorageEngine()
        let useCase = SearchRecordingsUseCase(storage: storage)

        _ = try await useCase.search(query: "")

        let called = await storage.listRecordingsCalled
        #expect(called == true)
    }

    @Test("execute with whitespace-only query delegates to storage.listRecordings")
    func executeWithWhitespaceOnlyQueryDelegatesToListRecordings() async throws {
        let storage = MockStorageEngine()
        let useCase = SearchRecordingsUseCase(storage: storage)

        _ = try await useCase.search(query: "   ")

        let called = await storage.listRecordingsCalled
        #expect(called == true)
    }

    // MARK: - Whitespace trimming

    @Test("execute trims whitespace from query before delegating to searchTranscripts")
    func executeTrimsWhitespaceFromQuery() async throws {
        let storage = MockStorageEngine()
        let recording = makeStoredRecording(id: RecordingID("rec-trim"), transcript: "hello world")
        await storage.seedRecording(recording)

        let useCase = SearchRecordingsUseCase(storage: storage)
        let results = try await useCase.search(query: " hello ")

        let searchCalled = await storage.searchTranscriptsCalled
        #expect(searchCalled == true)
        #expect(results.count == 1)
        #expect(results.first?.id == RecordingID("rec-trim"))
    }

    // MARK: - Results passthrough

    @Test("execute returns results from storage.searchTranscripts")
    func executeReturnsResultsFromStorage() async throws {
        let storage = MockStorageEngine()
        let r1 = makeStoredRecording(id: RecordingID("rec-A"), transcript: "quarterly review notes")
        let r2 = makeStoredRecording(id: RecordingID("rec-B"), transcript: "quarterly budget discussion")
        let r3 = makeStoredRecording(id: RecordingID("rec-C"), transcript: "unrelated content")
        await storage.seedRecording(r1)
        await storage.seedRecording(r2)
        await storage.seedRecording(r3)

        let useCase = SearchRecordingsUseCase(storage: storage)
        let results = try await useCase.search(query: "quarterly")

        #expect(results.count == 2)
        let ids = Set(results.map { $0.id })
        #expect(ids == Set([RecordingID("rec-A"), RecordingID("rec-B")]))
    }

    // MARK: - #151: injection shape

    /// The use case must take the named `SearchRepository` composition, not an
    /// inline compound existential — adding a third repository should change
    /// the alias, not every signature.
    @Test("#151: storage is injected as SearchRepository, not an inline compound")
    func storageInjectedAsSearchRepository() throws {
        let path = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent() // Record-App package root
            .appendingPathComponent("Sources/Business/UseCases/SearchRecordingsUseCase.swift")
        let source = try String(contentsOf: path, encoding: .utf8)
        #expect(!source.contains("RecordingReadRepository & TranscriptReadRepository"))
        #expect(source.contains("any SearchRepository"))
    }
}

import Domain
import Foundation
import Observation

@Observable
@MainActor
public final class ModelDownloadViewModel {
    // MARK: - State

    /// Full model list driving the download UI. Mutations trigger `modelsByCategory` recomputation.
    public var models: [ModelEntry] = ModelCatalog.all {
        didSet { modelsByCategory = Dictionary(grouping: models, by: \.category) }
    }

    /// Non-nil when a download fails; displayed as an inline error banner.
    public var errorMessage: String?
    /// Controls visibility of the custom model storage path picker sheet.
    public var isShowingPathPicker = false

    @ObservationIgnored
    private var downloadTasks: [ModelID: Task<Void, Never>] = [:]

    @ObservationIgnored
    private let downloadWhisper: @Sendable (ModelID, String?) async throws -> Void
    @ObservationIgnored
    private let downloadParakeet: @Sendable (ModelID, String?) async throws -> Void
    @ObservationIgnored
    private let downloadMLX: @Sendable (ModelID, String?) async throws -> Void
    @ObservationIgnored
    private let downloadDiarization: @Sendable () async throws -> Void

    // MARK: - Persisted settings

    @ObservationIgnored
    private let tokenStore: any TokenStore

    /// Cached once in init — avoids a Keychain read on every SwiftUI body eval.
    /// Persisted via the injected `TokenStore` on every change.
    public var hfToken: String {
        didSet {
            let newToken = hfToken
            let store = tokenStore
            // try? is intentional: didSet cannot be async or throw, and a Keychain
            // write failure in a fire-and-forget Task has no meaningful caller to
            // propagate to. The token is already cached in memory for this session.
            Task {
                if newToken.isEmpty {
                    try? store.deleteToken() // swiftlint:disable:this superfluous_disable_command
                } else {
                    try? store.saveToken(newToken) // swiftlint:disable:this superfluous_disable_command
                }
            }
        }
    }

    public var modelStoragePath: String {
        get {
            UserDefaults.standard.string(forKey: "therecord.modelStoragePath")
                ?? (
                    FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)
                        .first?.appendingPathComponent(AppConstants.Paths.huggingFaceHubPath).path ?? ""
                )
        }
        set { UserDefaults.standard.set(newValue, forKey: "therecord.modelStoragePath") }
    }

    // MARK: - Init

    public init(
        downloadWhisper: @escaping @Sendable (ModelID, String?) async throws -> Void,
        downloadParakeet: @escaping @Sendable (ModelID, String?) async throws -> Void,
        downloadMLX: @escaping @Sendable (ModelID, String?) async throws -> Void,
        downloadDiarization: @escaping @Sendable () async throws -> Void,
        tokenStore: any TokenStore
    ) {
        self.downloadWhisper = downloadWhisper
        self.downloadParakeet = downloadParakeet
        self.downloadMLX = downloadMLX
        self.downloadDiarization = downloadDiarization
        self.tokenStore = tokenStore
        hfToken = (try? tokenStore.loadToken()) ?? ""
    }

    // MARK: - Precomputed Groups

    /// Models grouped by category. Stored and updated via `models.didSet` — avoids
    /// rebuilding `Dictionary(grouping:)` on every access (#173).
    public private(set) var modelsByCategory: [ModelCategory: [ModelEntry]] =
        Dictionary(grouping: ModelCatalog.all, by: \.category)

    // MARK: - Actions

    public func checkAllStatuses() {
        let currentModels = models
        let currentStoragePath = modelStoragePath

        Task { [weak self] in
            let statuses = await Task.detached {
                var result: [ModelID: Bool] = [:]
                for model in currentModels {
                    result[model.id] = Self.checkIsDownloaded(model, storagePath: currentStoragePath)
                }
                return result
            }.value

            guard let self else { return }
            for i in self.models.indices {
                if let downloaded = statuses[self.models[i].id] {
                    self.models[i].status = downloaded ? .downloaded : .notDownloaded
                }
            }
        }
    }

    public func download(id: ModelID) {
        guard let idx = models.firstIndex(where: { $0.id == id }) else { return }
        guard !models[idx].status.isDownloading else { return }
        models[idx].status = .downloading(0)
        errorMessage = nil

        let token = hfToken.isEmpty ? nil : hfToken
        let model = models[idx]

        downloadTasks[id]?.cancel()
        downloadTasks[id] = Task { [weak self] in
            guard let self else { return }
            do {
                switch model.category {
                case .transcription:
                    if model.id == ModelIDs.parakeetPrimary {
                        try await downloadParakeet(model.id, token)
                    } else {
                        try await downloadWhisper(model.id, token)
                    }
                case .summarization:
                    try await downloadMLX(model.id, token)
                case .diarization:
                    try await downloadDiarization()
                }
                if let i = self.models.firstIndex(where: { $0.id == id }) {
                    self.models[i].status = .downloaded
                    UserDefaults.standard.set(true, forKey: "therecord.modelDownloaded.\(id)")
                }
            } catch {
                if let i = self.models.firstIndex(where: { $0.id == id }) {
                    self.models[i].status = .failed(error.userFacingMessage)
                }
                self.errorMessage = "\(model.displayName): \(error.userFacingMessage)"
            }
            self.downloadTasks.removeValue(forKey: id)
        }
    }

    // MARK: - Filesystem check

    private nonisolated static func checkIsDownloaded(_ model: ModelEntry, storagePath: String) -> Bool {
        // Trust a previously confirmed download — avoids fighting with WhisperKit's
        // internal cache layout (argmaxinc/whisperkit-coreml snapshot structure).
        if UserDefaults.standard.bool(forKey: "therecord.modelDownloaded.\(model.id)") { return true }

        let fm = FileManager.default
        switch model.category {
        case .diarization:
            let path = fm.urls(for: .applicationSupportDirectory, in: .userDomainMask)
                .first?.appendingPathComponent(AppConstants.Paths.fluidAudioDiarizationPath)
            return fm.fileExists(atPath: path?.path ?? "")

        case .summarization:
            // Check user-specified storage path first, then default HF cache
            let slug = model.hfRepo.replacingOccurrences(of: "/", with: "_")
            if fm.fileExists(atPath: storagePath + "/" + slug) { return true }
            let cache = fm.homeDirectoryForCurrentUser
                .appendingPathComponent(AppConstants.Paths.huggingFaceCacheBasePath)
                .appendingPathComponent("models--" + model.hfRepo.replacingOccurrences(of: "/", with: "--"))
            return fm.fileExists(atPath: cache.path)

        case .transcription:
            if model.id == ModelIDs.parakeetPrimary {
                let path = fm.urls(for: .applicationSupportDirectory, in: .userDomainMask)
                    .first?.appendingPathComponent(AppConstants.Paths.fluidAudioParakeetPath)
                return fm.fileExists(atPath: path?.path ?? "")
            }
            let base = fm.homeDirectoryForCurrentUser
                .appendingPathComponent(AppConstants.Paths.whisperKitSnapshotsPath)
            guard fm.fileExists(atPath: base.path) else { return false }
            do {
                let snapshots = try fm.contentsOfDirectory(atPath: base.path)
                return snapshots.contains {
                    fm
                        .fileExists(
                            atPath: base.appendingPathComponent($0).appendingPathComponent(model.id.rawValue)
                                .path
                        )
                }
            } catch {
                return false
            }
        }
    }
}

