import Testing
import Foundation
@testable import Domain

@Suite("withTimeout (Domain)")
struct TimeoutTests {

    @Test("returns the operation's value when it completes before the deadline")
    func valuePassesThrough() async throws {
        let result = try await withTimeout(.seconds(5)) { 42 }
        #expect(result == 42)
    }

    @Test("throws TimeoutError when the deadline elapses first")
    func deadlineThrowsTimeoutError() async {
        await #expect(throws: TimeoutError.self) {
            try await withTimeout(.milliseconds(10)) {
                try await Task.sleep(for: .seconds(60))
                return 0
            }
        }
    }

    @Test("operation errors propagate unwrapped, not as TimeoutError")
    func operationErrorPropagates() async {
        struct DomainSpecificFailure: Error {}
        await #expect(throws: DomainSpecificFailure.self) {
            try await withTimeout(.seconds(5)) {
                throw DomainSpecificFailure()
            }
        }
    }

    @Test("losing operation task is cancelled after timeout")
    func loserIsCancelled() async throws {
        let sawCancellation = Mutex()
        _ = try? await withTimeout(.milliseconds(10)) {
            do {
                try await Task.sleep(for: .seconds(60))
            } catch is CancellationError {
                await sawCancellation.set()
            }
            return 0
        }
        // Give the cancelled child a beat to run its catch block.
        try await Task.sleep(for: .milliseconds(50))
        #expect(await sawCancellation.get())
    }
}

/// Minimal async flag — Swift Testing has no built-in expectation primitive.
private actor Mutex {
    private var flag = false
    func set() { flag = true }
    func get() -> Bool { flag }
}

