import Testing
import Foundation
@testable import Business
import Domain
import TestMocks

/// #130 residual: post-stop sequencing (cleanup pass + main pipeline) is
/// Business knowledge. Presentation calls one entry point and must not know
/// the pass ordering.
@Suite("PipelineCoordinator recordingCompleted")
struct PipelineCoordinatorRecordingCompletedTests {

    private func makeTranscription() -> TranscriptionResult {
        TranscriptionResult(
            segments: [],
            fullText: "hello",
            processingTime: 0.1,
            modelId: ModelID("openai_whisper-tiny"),
            recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
            computeUnit: .cpuOnly,
            passType: .live,
        )
    }

    @Test("starts both the cleanup pass and the main pipeline")
    func startsCleanupAndPipeline() async {
        let coordinator = PipelineCoordinator(
            cleanupTranscribe: makePCCleanupUseCase(),
            diarizeMeeting: makePCDiarizeUseCase(),
            summarizeMeeting: makePCSummarizeUseCase(),
        )

        await coordinator.recordingCompleted(
            for: RecordingID("rec-130"),
            liveTranscription: makeTranscription(),
        )

        // Both tasks are scheduled synchronously inside the actor call —
        // the test accessors see them before either finishes.
        #expect(await coordinator.hasActiveCleanupTask)
        #expect(await coordinator.hasActivePipelineTask)
    }

    @Test("archive pass disabled: pipeline still starts, cleanup does not")
    func archiveGateStillRespected() async {
        let coordinator = PipelineCoordinator(
            cleanupTranscribe: makePCCleanupUseCase(),
            diarizeMeeting: makePCDiarizeUseCase(),
            summarizeMeeting: makePCSummarizeUseCase(),
            archivePassEnabled: false,
        )

        await coordinator.recordingCompleted(
            for: RecordingID("rec-130-gated"),
            liveTranscription: makeTranscription(),
        )

        #expect(!(await coordinator.hasActiveCleanupTask))
        #expect(await coordinator.hasActivePipelineTask)
    }
}

