import Testing
import Foundation
@testable import Business
import Domain
import TestMocks

/// #132: after the post-stop pipeline finishes, the coordinator releases
/// diarization + summarization model memory on memory-constrained machines —
/// the same policy it already applies to the ASR engine in the cleanup pass.
@Suite("PipelineCoordinator engine unload")
struct PipelineCoordinatorEngineUnloadTests {

    private static let constrainedMemory: UInt64 = 8_000_000_000
    private static let ampleMemory: UInt64 = 32_000_000_000

    private func makeTranscription() -> TranscriptionResult {
        TranscriptionResult(
            segments: [],
            fullText: "hello",
            processingTime: 0.1,
            modelId: ModelID("openai_whisper-tiny"),
            recordedAt: Date(timeIntervalSince1970: 1_700_000_000),
            computeUnit: .cpuOnly,
            passType: .live,
        )
    }

    private func runPipelineToCompletion(
        physicalMemory: UInt64,
        diarization: MockDiarizationEngine,
        summarization: MockSummarizationEngine,
    ) async throws {
        let coordinator = PipelineCoordinator(
            cleanupTranscribe: makePCCleanupUseCase(),
            diarizeMeeting: makePCDiarizeUseCase(),
            summarizeMeeting: makePCSummarizeUseCase(),
            physicalMemory: physicalMemory,
            archivePassEnabled: false,
            diarizationEngine: diarization,
            summarizationEngine: summarization,
        )
        await coordinator.startPipeline(for: RecordingID("rec-132"), liveTranscription: makeTranscription())
        // The mocks complete near-instantly; poll the task-lifecycle accessor.
        for _ in 0..<200 where await coordinator.hasActivePipelineTask {
            try await Task.sleep(for: .milliseconds(10))
        }
        #expect(!(await coordinator.hasActivePipelineTask))
    }

    @Test("memory-constrained machine: both engines unloaded after pipeline completes")
    func constrainedMemoryUnloadsEngines() async throws {
        let diarization = MockDiarizationEngine()
        let summarization = MockSummarizationEngine()
        try await runPipelineToCompletion(
            physicalMemory: Self.constrainedMemory,
            diarization: diarization,
            summarization: summarization,
        )
        #expect(await diarization.unloadModelCalled)
        #expect(await summarization.unloadModelCalled)
    }

    @Test("ample memory: engines stay resident for the next recording")
    func ampleMemoryKeepsEnginesResident() async throws {
        let diarization = MockDiarizationEngine()
        let summarization = MockSummarizationEngine()
        try await runPipelineToCompletion(
            physicalMemory: Self.ampleMemory,
            diarization: diarization,
            summarization: summarization,
        )
        #expect(!(await diarization.unloadModelCalled))
        #expect(!(await summarization.unloadModelCalled))
    }
}

