import Testing
import Foundation
@testable import Business
import Domain
import TestMocks

/// #133: engines register by capability; the composition root resolves them
/// instead of hardwiring concrete types at every seam.
@Suite("PluginRegistry")
struct PluginRegistryTests {

    @Test("registered transcription engine resolves by id")
    func resolveTranscriptionById() async {
        let registry = PluginRegistry()
        let engine = MockTranscriptionEngine()
        await registry.register(transcription: engine, id: "mock-asr")

        let resolved = await registry.transcription(id: "mock-asr")
        #expect(resolved != nil)
        #expect((resolved as AnyObject) === engine)
    }

    @Test("first registration becomes the capability default")
    func firstRegistrationIsDefault() async {
        let registry = PluginRegistry()
        let first = MockSummarizationEngine()
        let second = MockSummarizationEngine()
        await registry.register(summarization: first, id: "first")
        await registry.register(summarization: second, id: "second")

        let resolved = await registry.summarization()
        #expect((resolved as AnyObject) === first)
    }

    @Test("setDefault overrides the first-registered default")
    func setDefaultOverrides() async {
        let registry = PluginRegistry()
        let first = MockDiarizationEngine()
        let second = MockDiarizationEngine()
        await registry.register(diarization: first, id: "first")
        await registry.register(diarization: second, id: "second")
        let switched = await registry.setDefault(.diarization, id: "second")
        #expect(switched)

        let resolved = await registry.diarization()
        #expect((resolved as AnyObject) === second)
    }

    @Test("unknown id resolves nil; setDefault to unknown id is refused")
    func unknownIdIsNil() async {
        let registry = PluginRegistry()
        #expect(await registry.transcription(id: "nope") == nil)
        #expect(await registry.summarization() == nil)
        #expect(!(await registry.setDefault(.transcription, id: "nope")))
    }

    @Test("registeredIDs lists ids per capability in registration order")
    func registeredIDsListed() async {
        let registry = PluginRegistry()
        await registry.register(transcription: MockTranscriptionEngine(), id: "a")
        await registry.register(transcription: MockTranscriptionEngine(), id: "b")
        #expect(await registry.registeredIDs(for: .transcription) == ["a", "b"])
        #expect(await registry.registeredIDs(for: .diarization).isEmpty)
    }
}

