import Foundation
import Domain

/// #133: runtime home for ML engine conformances, keyed by capability.
///
/// The composition root registers every engine it builds; seams that need an
/// engine resolve it here instead of hardwiring a concrete type. Adding a new
/// provider is: conform to the Domain protocol, register in one line.
///
/// The first registration for a capability becomes its default; a later
/// ``setDefault(_:id:)`` (e.g. from a future Settings picker) switches it.
public actor PluginRegistry {

    public enum Capability: String, Sendable, CaseIterable {
        case transcription
        case summarization
        case diarization
    }

    private var transcriptionEngines: [(id: String, engine: any TranscriptionEngine)] = []
    private var summarizationEngines: [(id: String, engine: any SummarizationEngine)] = []
    private var diarizationEngines: [(id: String, engine: any DiarizationEngine)] = []
    private var defaults: [Capability: String] = [:]

    public init() {}

    // MARK: - Registration

    public func register(transcription engine: any TranscriptionEngine, id: String) {
        transcriptionEngines.append((id, engine))
        defaults[.transcription] = defaults[.transcription] ?? id
    }

    public func register(summarization engine: any SummarizationEngine, id: String) {
        summarizationEngines.append((id, engine))
        defaults[.summarization] = defaults[.summarization] ?? id
    }

    public func register(diarization engine: any DiarizationEngine, id: String) {
        diarizationEngines.append((id, engine))
        defaults[.diarization] = defaults[.diarization] ?? id
    }

    // MARK: - Resolution

    /// Resolves a transcription engine; `nil` id means the capability default.
    public func transcription(id: String? = nil) -> (any TranscriptionEngine)? {
        lookup(transcriptionEngines, capability: .transcription, id: id)
    }

    /// Resolves a summarization engine; `nil` id means the capability default.
    public func summarization(id: String? = nil) -> (any SummarizationEngine)? {
        lookup(summarizationEngines, capability: .summarization, id: id)
    }

    /// Resolves a diarization engine; `nil` id means the capability default.
    public func diarization(id: String? = nil) -> (any DiarizationEngine)? {
        lookup(diarizationEngines, capability: .diarization, id: id)
    }

    // MARK: - Defaults & introspection

    /// Switches the capability default. Refused (returns `false`) when no
    /// engine with that id is registered, so a stale Settings value can never
    /// unset a working default.
    public func setDefault(_ capability: Capability, id: String) -> Bool {
        guard registeredIDs(for: capability).contains(id) else { return false }
        defaults[capability] = id
        return true
    }

    public func registeredIDs(for capability: Capability) -> [String] {
        switch capability {
        case .transcription: transcriptionEngines.map(\.id)
        case .summarization: summarizationEngines.map(\.id)
        case .diarization: diarizationEngines.map(\.id)
        }
    }

    // MARK: - Private

    private func lookup<E>(
        _ entries: [(id: String, engine: E)],
        capability: Capability,
        id: String?,
    ) -> E? {
        guard let wanted = id ?? defaults[capability] else { return nil }
        return entries.first(where: { $0.id == wanted })?.engine
    }
}

