export const meta = {
  name: 'beta-readiness-audit',
  description: 'Multi-agent beta-readiness audit: 6 dimensions, adversarially verified, max 2 concurrent',
  phases: [
    { title: 'Find', detail: 'six audit dimensions, 2 at a time' },
    { title: 'Verify', detail: 'one adversarial skeptic per finding, 2 at a time' },
  ],
}

const FINDINGS_SCHEMA = {
  type: 'object',
  required: ['findings'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        required: ['title', 'file', 'severity', 'evidence', 'beta_blocker'],
        properties: {
          title: { type: 'string' },
          file: { type: 'string', description: 'repo-relative path, with :line if known' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          evidence: { type: 'string', description: 'concrete code/config evidence, quoted' },
          failure_scenario: { type: 'string' },
          beta_blocker: { type: 'boolean' },
          suggested_fix: { type: 'string' },
        },
      },
    },
  },
}

const VERDICT_SCHEMA = {
  type: 'object',
  required: ['refuted', 'reason'],
  properties: {
    refuted: { type: 'boolean' },
    reason: { type: 'string' },
    severity_adjustment: { type: 'string', enum: ['keep', 'upgrade', 'downgrade'] },
  },
}

const COMMON = `You are auditing the-record-suite (repo root: /Volumes/Extra/repos/gitrdunhq/the-record-suite) — THE RECORD, a local-first macOS meeting transcription app (Swift 6.2 monorepo, Clean Architecture: Domain/Business/Infrastructure/Presentation). It is preparing for a PUBLIC BETA release.

Already-known issues — do NOT re-report these:
- #301 DataEraser has only a NoOpDataEraser placeholder (Delete All Data disabled)
- #215 protocol divergence between Record-Foundation and Record-CrossPlatform-Foundation (incl. missing unloadModel)
- #41 test suite timeout with --parallel integration runs
- #134 possibly-inverted test assertions in Record-Presentation
- Entitlements: sandbox off, camera entitlement present, no hardened runtime (release.sh)
- Missing: app icon, privacy policy, Sparkle auto-update, onboarding (tracked issues #70/#67/#118/#117)
- Vendored Prebuilts/ npm/pip dep vulns (build tooling only)

Ignore .build/, .temp/, Prebuilts/ vendored code, and Tools/ProofHarness (dev tooling) unless it affects the shipped app. Focus on what ships in the app bundle.

Report ONLY defects you can support with quoted code evidence you actually read. Severity: critical = data loss / privacy breach / crash on common path; high = broken user promise or likely beta-visible failure; medium = degraded UX or latent risk; low = polish. Set beta_blocker=true only for things that must be fixed before strangers run this app.`

const DIMENSIONS = [
  { key: 'privacy', prompt: `${COMMON}

DIMENSION: privacy claims vs reality. The app is marketed local-first. Hunt for: any network egress (URLSession, sockets, telemetry, model downloads — where do WhisperKit/FluidAudio/MLX models come from and is that disclosed?), what data is written where (recordings, transcripts, DBs — paths, file protection), anything sent to third parties, log statements leaking transcript/PII content (check privacy: .public annotations on OSLog interpolations carrying user content).` },
  { key: 'data-loss', prompt: `${COMMON}

DIMENSION: crash resilience and data loss on the record→transcribe→store path. What happens to in-flight audio if the app crashes or is force-quit mid-recording? Is the WAV flushed incrementally or buffered in memory? Is there recovery on next launch? What if the disk fills? What if transcription fails after a 2-hour meeting — is the audio preserved? Look at Record-App/Sources and Record-Audio/Sources capture + storage paths.` },
  { key: 'security', prompt: `${COMMON}

DIMENSION: security of stored data and secrets. Where are API tokens/keys stored (Keychain vs UserDefaults vs plaintext)? DB and recording file permissions? Any shell-out/Process invocations with user-influenced input? MCP server (JSON-RPC) exposure — does it bind a port/socket, any auth? Check Record-App/Sources/Infrastructure and Record-Storage.` },
  { key: 'concurrency', prompt: `${COMMON}

DIMENSION: concurrency correctness for a long-running menu-bar app. Unstructured Task {} without cancellation on deinit/stop, actor reentrancy bugs (state checked before await, mutated after), @unchecked Sendable outside the allowed audio paths, timers/loops that survive their owner, main-actor blocking (sync waits, heavy work on @MainActor). Focus on Record-App/Sources/Business and Record-Presentation ViewModels.` },
  { key: 'first-run', prompt: `${COMMON}

DIMENSION: first-run and permission-denial experience for a stranger's machine. Trace the cold-start path: no mic permission, no screen-recording permission, no calendar permission, models not yet downloaded, no network during model download. Does the app explain state or silently fail? Are permission denials surfaced with recovery instructions? Check Record-App/Sources/TheRecord (composition root, App.swift) and Presentation ViewModels for permission handling.` },
  { key: 'test-gaps', prompt: `${COMMON}

DIMENSION: test-coverage gaps on beta-critical paths, plus the #134 claim of inverted assertions. Sample Record-Presentation/Tests for tests that assert current-buggy behavior (comments like "locks in", expecting error/empty where success is the spec). Identify critical production paths with zero test coverage (recording stop/save, storage migration, export). List concrete files. Do not run the test suite; read code.` },
]

// Rate-limit rule: max 2 concurrent agents. Process dimensions in pairs.
const allFindings = []
for (let i = 0; i < DIMENSIONS.length; i += 2) {
  const pair = DIMENSIONS.slice(i, i + 2)
  const results = await parallel(pair.map(d => () =>
    agent(d.prompt, { label: `find:${d.key}`, phase: 'Find', schema: FINDINGS_SCHEMA })))
  results.filter(Boolean).forEach((r, j) => {
    r.findings.forEach(f => allFindings.push({ ...f, dimension: pair[j].key }))
  })
  log(`Find: ${Math.min(i + 2, DIMENSIONS.length)}/${DIMENSIONS.length} dimensions done, ${allFindings.length} findings so far`)
}

// Dedup by file+title similarity (cheap key)
const seen = new Set()
const deduped = allFindings.filter(f => {
  const k = (f.file.split(':')[0] + '|' + f.title.toLowerCase().slice(0, 40))
  if (seen.has(k)) return false
  seen.add(k)
  return true
})
log(`${deduped.length} findings after dedup (${allFindings.length - deduped.length} dropped)`)

// Verify: one adversarial skeptic per finding, 2 at a time
const verified = []
for (let i = 0; i < deduped.length; i += 2) {
  const pair = deduped.slice(i, i + 2)
