    agent(`You are an adversarial reviewer for the-record-suite (repo root: /Volumes/Extra/repos/gitrdunhq/the-record-suite). Try to REFUTE this beta-audit finding by reading the actual code. A finding is refuted if the evidence is misread, the scenario cannot occur, it is already mitigated elsewhere, or it is dev-only code that does not ship. Default to refuted=true if you cannot confirm it from the code.

FINDING: ${f.title}
FILE: ${f.file}
SEVERITY CLAIMED: ${f.severity}
EVIDENCE: ${f.evidence}
SCENARIO: ${f.failure_scenario || 'n/a'}`,
      { label: `verify:${f.title.slice(0, 30)}`, phase: 'Verify', schema: VERDICT_SCHEMA })))
  verdicts.forEach((v, j) => {
    if (v && !v.refuted) verified.push({ ...pair[j], verdict: v })
    else if (v) log(`refuted: ${pair[j].title.slice(0, 60)} — ${v.reason.slice(0, 100)}`)
  })
}

